import React, { useEffect, useState } from "react";

import { StudioProApi } from "@mendix/extensions-api";
import { Link } from "@mendix/ide-ui-components/link/Link";

import { handleImportKeyFromPortal, handleSelectKnowledgebaseKey, handleViewCollections } from "./mxCloudGenAIHandlers";

import { ConstantIcon } from "@mendix/ide-icons/ConstantIcon";
import { useDependentDocumentChanges } from "@src/hooks/useDependentDocumentChanges";
import styled from "styled-components";
import { cohereIconBase64 } from "../../../icons/modelIcons";
import { Knowledgebase } from "../../../types/knowledgebase/knowledgebase";
import { Collection, MxCloudGenAIKnowledgebaseFields } from "../../../types/knowledgebase/mxCloudGenAIKnowledgebase";
import { handleShowConstant } from "../../../utils/constantUtils";
import { clearKnowledgebaseDetails } from "../../../utils/knowledgebaseUtils";
import {
    ConstantValidationError,
    ConstantValidationErrors,
    validateStringConstant,
} from "../../../utils/validationUtils";
import { WarningBanner } from "../../components/Banner";
import ButtonWithLabel from "../../components/ButtonWithLabel";
import { DivFlexColumn, DivFlexRow, StyledLabel } from "../../components/elements/formelements";
import { BoldText } from "../../components/elements/text";
import GroupBox from "../../components/GroupBox";
import Table from "../../components/Table";
import TextInputLabeled from "../../components/TextInputLabeled";
import TextInputWithButton from "../../components/TextInputWithButton";

interface MxCloudGenAIProps {
    studioPro: StudioProApi;
    knowledgebase: Knowledgebase;
    setKnowledgebase: React.Dispatch<React.SetStateAction<Knowledgebase>>;
    updateStudioProDocument: (knowledgebase: Knowledgebase) => Promise<void>;
}

const emptyOnChange = () => {};

const LastSyncedTimestamp = styled.div`
    color: ${({ theme }) => theme.colorsTextSecondaryDefault};
    font-size: 10px;
`;

const MxCloudGenAI: React.FC<MxCloudGenAIProps> = ({
    studioPro,
    knowledgebase,
    setKnowledgebase,
    updateStudioProDocument,
}) => {
    const [keyValidationError, setKeyValidationError] = useState<ConstantValidationError | undefined>();
    const [collectionsLoaded, setCollectionsLoaded] = useState(false);
    const [collections, setCollections] = useState<Collection[]>([]);
    const [lastSynced, setLastSynced] = useState<Date | null>(null);
    const providerFields = knowledgebase.providerFields as MxCloudGenAIKnowledgebaseFields;

    const viewCollections = async () => {
        setCollectionsLoaded(false);

        const result = await handleViewCollections(studioPro, knowledgebase);
        if (result === undefined) {
            setCollections([]);
            setLastSynced(null);
            return;
        }
        setCollections(result);
        setCollectionsLoaded(true);
        setLastSynced(new Date());
    };

    const showConstant = async () => {
        if (providerFields.key) {
            handleShowConstant(studioPro, providerFields.key);
        }
    };

    const validateAndImportKey = async (knowledgebase: Knowledgebase) => {
        const providerFields = knowledgebase.providerFields as MxCloudGenAIKnowledgebaseFields;
        const error = await validateStringConstant(studioPro, providerFields.key);

        setKeyValidationError(error);

        if (!error) {
            handleImportKeyFromPortal(
                studioPro,
                knowledgebase,
                setKnowledgebase,
                setKeyValidationError,
                updateStudioProDocument
            );
        } else {
            const clearedKnowledgebase = clearKnowledgebaseDetails(knowledgebase);
            setKnowledgebase(clearedKnowledgebase);
            updateStudioProDocument(clearedKnowledgebase);
        }
    };

    const selectKey = async () => {
        const updatedKnowledgebase = await handleSelectKnowledgebaseKey(studioPro, knowledgebase);

        if (updatedKnowledgebase) {
            setCollections([]);
            setLastSynced(null);
            setKnowledgebase(updatedKnowledgebase);
            updateStudioProDocument(updatedKnowledgebase);
            await validateAndImportKey(updatedKnowledgebase);
        }
    };

    const onDependentDocumentsChanged = (changes: string[]) => {
        if (
            (providerFields.key && changes.includes(providerFields.key.documentId)) ||
            changes.includes("projectSettings")
        ) {
            validateAndImportKey(knowledgebase);
        }
    };

    useDependentDocumentChanges({
        studioPro,
        dependentIds: [providerFields.key?.documentId].filter((id): id is string => !!id),
        watchProjectSettings: true,
        onDependentDocumentsChanged,
    });

    useEffect(() => {
        validateAndImportKey(knowledgebase);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const getErrorMessage = (error: ConstantValidationError | undefined): string | true => {
        if (error === ConstantValidationErrors.Required) {
            return "Knowledge base key is required";
        } else if (error === ConstantValidationErrors.NotFound) {
            return "Selected constant not found. It might have been deleted or renamed. Please update the constant selection.";
        } else if (error === ConstantValidationErrors.InvalidType) {
            return "Selected constant must be of type string.";
        } else if (error === ConstantValidationErrors.Excluded) {
            return "Selected constant is excluded from the project and cannot be used.";
        }

        return true;
    };

    const showConstantWarning =
        keyValidationError === ConstantValidationErrors.EmptyValue ||
        keyValidationError === ConstantValidationErrors.InvalidContent ||
        keyValidationError === ConstantValidationErrors.PrivateValue;

    return (
        <>
            <GroupBox label="Resource">
                <TextInputWithButton
                    label="Knowledge base key"
                    ariaLabel="Knowledge base key"
                    value={providerFields.key?.qualifiedName ?? ""}
                    icon={providerFields.key ? <ConstantIcon /> : undefined}
                    buttonCaption="Select..."
                    onClick={selectKey}
                    onClickSecondary={providerFields.key ? showConstant : undefined}
                    validate={() => getErrorMessage(keyValidationError)}
                    buttonCaptionSecondary={providerFields.key ? "Show" : undefined}
                />
                {showConstantWarning && (
                    <WarningBanner>
                        <BoldText>
                            {keyValidationError === ConstantValidationErrors.PrivateValue
                                ? "Missing permissions"
                                : "Invalid constant value"}
                        </BoldText>
                        <div>
                            {keyValidationError === ConstantValidationErrors.PrivateValue
                                ? "Private constants require additional permissions for local use. Grant access via View > Extensions and reopen the current tab."
                                : "In order to use your Knowledge base locally, please set a valid value for the key constant."}
                        </div>
                    </WarningBanner>
                )}
                {!providerFields.key && (
                    <DivFlexRow>
                        <DivFlexColumn>
                            <StyledLabel></StyledLabel>
                        </DivFlexColumn>
                        <DivFlexColumn fullWidth>
                            <Link
                                href="https://genai.home.mendix.com/p/resources"
                                target="_blank"
                                rel="noreferrer,noopener"
                            >
                                Create a key in the portal
                            </Link>
                        </DivFlexColumn>
                    </DivFlexRow>
                )}
                {providerFields.keyId && (
                    <>
                        <TextInputLabeled
                            label="Resource"
                            ariaLabel="Resource name"
                            value={knowledgebase.name}
                            onChange={emptyOnChange}
                            readOnly={true}
                        />
                        <TextInputLabeled
                            label="Embeddings model"
                            ariaLabel="Embeddings model name"
                            value={providerFields.modelDisplayName}
                            icon={
                                providerFields.modelDisplayName &&
                                providerFields.modelDisplayName.toLocaleLowerCase().includes("cohere")
                                    ? cohereIconBase64
                                    : undefined
                            }
                            onChange={emptyOnChange}
                            readOnly={true}
                        />
                        <TextInputLabeled
                            label="Embeddings model ID"
                            ariaLabel="Embeddings model ID"
                            value={providerFields.modelName}
                            onChange={emptyOnChange}
                            readOnly={true}
                        />
                        <TextInputLabeled
                            label="Key"
                            ariaLabel="Key name"
                            value={providerFields.keyName}
                            onChange={emptyOnChange}
                            readOnly={true}
                        />
                        <TextInputLabeled
                            label="Environment"
                            ariaLabel="Environment"
                            value={providerFields.environment}
                            onChange={emptyOnChange}
                            readOnly={true}
                        />
                        <DivFlexRow>
                            <DivFlexColumn>
                                <StyledLabel></StyledLabel>
                            </DivFlexColumn>
                            <DivFlexColumn fullWidth>
                                <Link href={providerFields.deepLinkURL} target="_blank" rel="noreferrer,noopener">
                                    View resource in the portal
                                </Link>
                            </DivFlexColumn>
                        </DivFlexRow>
                    </>
                )}
            </GroupBox>
            {providerFields.keyId && (
                <GroupBox label="Configured Collections">
                    <ButtonWithLabel label="Collections" buttonCaption="List collections" onPress={viewCollections} />
                    {collectionsLoaded && (
                        <>
                            {lastSynced && (
                                <LastSyncedTimestamp>Last updated: {lastSynced.toLocaleString()}</LastSyncedTimestamp>
                            )}
                            <Table
                                ariaLabel="Collections table"
                                columns={[
                                    {
                                        id: "name",
                                        caption: "Name",
                                        resizable: true,
                                        isRowHeader: true,
                                    },
                                ]}
                                data={collections.map((collection) => [
                                    {
                                        cellContent: collection.name,
                                        tooltipText: collection.name,
                                    },
                                ])}
                            />
                        </>
                    )}
                </GroupBox>
            )}
        </>
    );
};

export default MxCloudGenAI;
